const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [];
const d = new Date().toLocaleDateString('es-MX', { day: 'numeric', month: 'short', timeZone: 'America/Monterrey' });
const lines = rows.map(r => '• ' + r.fullName + ' (' + r.expectedAt + ')');
const text = '⏰ *Sin capturar entrada (13:00) — ' + d + '*\n' + lines.join('\n');
return [{ json: { text } }];
